#include "sea_nuclear_wave.hpp"
#include <algorithm>
#include <cmath>
#include <cstdio>
int main(){bool ok=true;for(float scale:{1.f,10.f})for(float age:{1.f,5.f,12.f,35.f}){SeaNuclearWave w{0,0,0,0,true,scale};w.Advance(age);if(!w.active){std::printf("scale=%.0f age=%.0f expired=1\n",scale,age);continue;}float maxError=0,lo=1e9f,hi=-1e9f,maxFoam=0;int n=0;for(int a=0;a<96;a++){float theta=6.283185307f*a/96.f;for(int i=0;i<220;i++){float r=std::max(.2f,w.Front()+w.sampleWidth*(float(i)/50.f-2.f));float x=r*std::cos(theta),z=r*std::sin(theta),e=.05f;auto s=EvaluateSeaNuclearWave(w,x,z);auto xp=EvaluateSeaNuclearWave(w,x+e,z),xm=EvaluateSeaNuclearWave(w,x-e,z),zp=EvaluateSeaNuclearWave(w,x,z+e),zm=EvaluateSeaNuclearWave(w,x,z-e);maxError=std::max({maxError,std::abs((xp.height-xm.height)/(2*e)-s.slopeX),std::abs((zp.height-zm.height)/(2*e)-s.slopeZ)});lo=std::min(lo,s.height);hi=std::max(hi,s.height);maxFoam=std::max(maxFoam,s.foam);if(s.height<-.0001f)n++;}}std::printf("scale=%.0f age=%.0f front=%.1f amplitude=%.3f min=%.3f max=%.3f foam=%.3f slope_error=%.5f trough_samples=%d\n",scale,age,w.Front(),w.amplitude,lo,hi,maxFoam,maxError,n);ok &= maxError<.02f && hi<=w.amplitude+1e-4f && maxFoam<=1.f && (age<12.f || n>0);}return !ok;}
